CREATE TABLE "doctors" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "specialty" TEXT NULL, "phone" TEXT NULL, "email" TEXT NULL, "clinic" TEXT NULL, "address" TEXT NULL, "consultation_fee_minor" INTEGER NULL, "notes" TEXT NULL, "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "expenses" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "category" TEXT NOT NULL, "title" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "quantity" REAL NULL, "medicine_id" INTEGER NULL REFERENCES medicines (id) ON DELETE SET NULL, "doctor_id" INTEGER NULL REFERENCES doctors (id) ON DELETE SET NULL, "receipt_record_id" INTEGER NULL REFERENCES records (id) ON DELETE SET NULL, "spent_on" INTEGER NOT NULL, "notes" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), CHECK (amount_minor >= 0));
CREATE TABLE "medicines" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "strength" TEXT NULL, "form" TEXT NOT NULL DEFAULT 'tablet', "dose_amount" REAL NOT NULL DEFAULT 1.0, "dose_unit" TEXT NOT NULL DEFAULT 'tablet', "meal_relation" TEXT NOT NULL DEFAULT 'anytime', "doctor_id" INTEGER NULL REFERENCES doctors (id) ON DELETE SET NULL, "prescription_id" INTEGER NULL REFERENCES records (id) ON DELETE SET NULL, "unit_price_minor" INTEGER NOT NULL DEFAULT 0, "stock_quantity" REAL NULL, "refill_threshold" REAL NULL, "start_date" INTEGER NOT NULL, "end_date" INTEGER NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "notes" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), CHECK (dose_amount > 0), CHECK (unit_price_minor >= 0));
CREATE TABLE "record_attachments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "record_id" INTEGER NOT NULL REFERENCES records (id) ON DELETE CASCADE, "relative_path" TEXT NOT NULL, "mime_type" TEXT NOT NULL DEFAULT 'image/jpeg', "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "records" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "doctor_id" INTEGER NULL REFERENCES doctors (id) ON DELETE SET NULL, "record_date" INTEGER NOT NULL, "notes" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "reminder_logs" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "reminder_id" INTEGER NOT NULL REFERENCES reminders (id) ON DELETE CASCADE, "scheduled_for" INTEGER NOT NULL, "status" TEXT NOT NULL, "acted_at" INTEGER NULL, UNIQUE ("reminder_id", "scheduled_for"));
CREATE TABLE "reminders" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NULL, "medicine_id" INTEGER NULL REFERENCES medicines (id) ON DELETE CASCADE, "doctor_id" INTEGER NULL REFERENCES doctors (id) ON DELETE SET NULL, "location" TEXT NULL, "start_at" INTEGER NOT NULL, "repeat_rule" TEXT NOT NULL DEFAULT 'once', "repeat_interval" INTEGER NULL, "weekdays_mask" INTEGER NULL, "end_at" INTEGER NULL, "next_trigger_at" INTEGER NULL, "ringing_for" INTEGER NULL, "is_critical" INTEGER NOT NULL DEFAULT 1 CHECK ("is_critical" IN (0, 1)), "is_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("is_enabled" IN (0, 1)), "snooze_minutes" INTEGER NOT NULL DEFAULT 10, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), CHECK (type <> 'medicine' OR medicine_id IS NOT NULL), CHECK (repeat_rule <> 'everyNDays' OR (repeat_interval IS NOT NULL AND repeat_interval >= 1)), CHECK (repeat_rule <> 'weekly' OR (weekdays_mask IS NOT NULL AND weekdays_mask BETWEEN 1 AND 127)));
CREATE INDEX idx_attachments_record ON record_attachments (record_id);
CREATE INDEX idx_expenses_doctor ON expenses (doctor_id);
CREATE INDEX idx_expenses_medicine ON expenses (medicine_id);
CREATE INDEX idx_expenses_spent_on ON expenses (spent_on);
CREATE INDEX idx_medicines_active ON medicines (is_active);
CREATE INDEX idx_medicines_doctor ON medicines (doctor_id);
CREATE INDEX idx_records_doctor ON records (doctor_id);
CREATE INDEX idx_records_type_date ON records (type, record_date);
CREATE INDEX idx_reminder_logs_reminder ON reminder_logs (reminder_id);
CREATE INDEX idx_reminders_doctor ON reminders (doctor_id);
CREATE INDEX idx_reminders_medicine ON reminders (medicine_id);
CREATE INDEX idx_reminders_next ON reminders (is_enabled, next_trigger_at);
